package com.amdocs.telecom.service; import java.sql.*; import java.util.*; import com.amdocs.telecom.util.DBConnection;
public class EngineerAssignmentService { public List<Map<String,Object>> recommend(String skill,String region)throws SQLException{List<Map<String,Object>> a=new ArrayList<>();try(Connection c=DBConnection.getInstance().get();PreparedStatement p=c.prepareStatement("SELECT * FROM network_engineers WHERE availability=TRUE")){try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object>m=new HashMap<>();m.put("engineerId",r.getString("engineer_id"));m.put("name",r.getString("engineer_name"));m.put("specialization",r.getString("specialization"));m.put("region",r.getString("region"));m.put("experience",r.getInt("experience_years"));m.put("workload",r.getInt("active_ticket_count"));a.add(m);}}}return a.stream().filter(x->skill==null||String.valueOf(x.get("specialization")).toLowerCase().contains(skill.toLowerCase())).filter(x->region==null||region.equalsIgnoreCase(String.valueOf(x.get("region")))).sorted(Comparator.comparingInt((Map<String,Object>x)->(Integer)x.get("workload")).thenComparing((x,y)->Integer.compare((Integer)y.get("experience"),(Integer)x.get("experience")))).limit(3).collect(java.util.stream.Collectors.toList());}
 public void assign(long ticketId,String engineerId,String actor)throws SQLException{try(Connection c=DBConnection.getInstance().get()){c.setAutoCommit(false);Savepoint sp=c.setSavepoint();try{String old;try(PreparedStatement p=c.prepareStatement("SELECT status FROM trouble_tickets WHERE ticket_id=? FOR UPDATE")){p.setLong(1,ticketId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Ticket not found");old=r.getString(1);}}try(PreparedStatement p=c.prepareStatement("SELECT availability FROM network_engineers WHERE engineer_id=? FOR UPDATE")){p.setString(1,engineerId);try(ResultSet r=p.executeQuery()){if(!r.next()||!r.getBoolean(1))throw new SQLException("Engineer unavailable");}}try(PreparedStatement p=c.prepareStatement("UPDATE trouble_tickets SET assigned_engineer_id=?,status='ASSIGNED',updated_at=CURRENT_TIMESTAMP WHERE ticket_id=?")){p.setString(1,engineerId);p.setLong(2,ticketId);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE network_engineers SET active_ticket_count=active_ticket_count+1 WHERE engineer_id=?")){p.setString(1,engineerId);p.executeUpdate();}history(c,ticketId,old,"ASSIGNED",actor,"Engineer assigned");notification(c,engineerId,"Ticket assigned: "+ticketId,"ENGINEER_ASSIGNMENT");audit(c,actor,"ASSIGN","TICKET",String.valueOf(ticketId),engineerId);c.commit();}catch(Exception e){c.rollback(sp);c.rollback();throw e instanceof SQLException?(SQLException)e:new SQLException(e);}}}
 private void history(Connection c,long id,String old,String ne,String actor,String rem)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO ticket_status_history(ticket_id,old_status,new_status,changed_by,remarks) VALUES(?,?,?,?,?)")){p.setLong(1,id);p.setString(2,old);p.setString(3,ne);p.setString(4,actor);p.setString(5,rem);p.executeUpdate();}}private void notification(Connection c,String r,String m,String t)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO notifications(recipient_id,message,notification_type) VALUES(?,?,?)")){p.setString(1,r);p.setString(2,m);p.setString(3,t);p.executeUpdate();}}private void audit(Connection c,String a,String ac,String et,String id,String d)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO audit_log(actor,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)")){p.setString(1,a);p.setString(2,ac);p.setString(3,et);p.setString(4,id);p.setString(5,d);p.executeUpdate();}}
}
